// simple fifo implementation
module xls_fifo_wrapper (
clk, rst,
push_ready, push_data, push_valid,
pop_ready,  pop_data,  pop_valid);
  parameter int Width = 32,
                Depth = 32,
                EnableBypass = 0,
                RegisterPushOutputs = 1,
                RegisterPopOutputs = 1;
  localparam int AddrWidth = $clog2(Depth) + 1;
  input  wire             clk;
  input  wire             rst;
  output wire             push_ready;
  input  wire [Width-1:0] push_data;
  input  wire             push_valid;
  input  wire             pop_ready;
  output wire [Width-1:0] pop_data;
  output wire             pop_valid;

  // Require depth be 1 and bypass disabled.
  //initial begin
  //  if (EnableBypass || Depth != 1 || !RegisterPushOutputs || RegisterPopOutputs) begin
  //    // FIFO configuration not supported.
  //    $fatal(1);
  //  end
  //end


  reg [Width-1:0] mem;
  reg full;

  assign push_ready = !full;
  assign pop_valid = full;
  assign pop_data = mem;

  always @(posedge clk) begin
    if (rst == 1'b1) begin
      full <= 1'b0;
    end else begin
      if (push_valid && push_ready) begin
        mem <= push_data;
        full <= 1'b1;
      end else if (pop_valid && pop_ready) begin
        mem <= mem;
        full <= 1'b0;
      end else begin
        mem <= mem;
        full <= full;
      end
    end
  end
endmodule

"""
  )
  val text: String = parts.mkString
}

/** 仿真外壳：隐式时钟/复位，数据端口 1:1 直连（与 Shell 同构）。 */
final class IngressPipelineSimDut extends Module {
  val io = IO(new Bundle {
    val pkt_in = Input(UInt(512.W))
    val pkt_in_vld = Input(Bool())
    val tbl_mac_table_rsp = Input(UInt(6.W))
    val tbl_mac_table_rsp_vld = Input(Bool())
    val tbl_route_table_rsp = Input(UInt(102.W))
    val tbl_route_table_rsp_vld = Input(Bool())
    val pkt_out_rdy = Input(Bool())
    val ex_portBytes = Output(UInt(256.W))
    val ex_portBytes_vld = Output(Bool())
    val ex_fwdCnt = Output(UInt(128.W))
    val ex_fwdCnt_vld = Output(Bool())
    val tbl_mac_table_key = Output(UInt(48.W))
    val tbl_mac_table_key_vld = Output(Bool())
    val tbl_route_table_key = Output(UInt(40.W))
    val tbl_route_table_key_vld = Output(Bool())
    val pkt_out = Output(UInt(500.W))
    val pkt_out_vld = Output(Bool())
  })
  private val ext = Module(new IngressPipelineSimExt)
  ext.io.clk := clock
  ext.io.rst := reset.asBool
  ext.io.pkt_in := io.pkt_in
  ext.io.pkt_in_vld := io.pkt_in_vld
  ext.io.tbl_mac_table_rsp := io.tbl_mac_table_rsp
  ext.io.tbl_mac_table_rsp_vld := io.tbl_mac_table_rsp_vld
  ext.io.tbl_route_table_rsp := io.tbl_route_table_rsp
  ext.io.tbl_route_table_rsp_vld := io.tbl_route_table_rsp_vld
  ext.io.pkt_out_rdy := io.pkt_out_rdy
  io.ex_portBytes := ext.io.ex_portBytes
  io.ex_portBytes_vld := ext.io.ex_portBytes_vld
  io.ex_fwdCnt := ext.io.ex_fwdCnt
  io.ex_fwdCnt_vld := ext.io.ex_fwdCnt_vld
  io.tbl_mac_table_key := ext.io.tbl_mac_table_key
  io.tbl_mac_table_key_vld := ext.io.tbl_mac_table_key_vld
  io.tbl_route_table_key := ext.io.tbl_route_table_key
  io.tbl_route_table_key_vld := ext.io.tbl_route_table_key_vld
  io.pkt_out := ext.io.pkt_out
  io.pkt_out_vld := ext.io.pkt_out_vld
}

/** svsim 仿真器：Verilator 后端 + FST 波形（chisel 7 起支持 FST，5.3/6.x 只有 VCD）。 */
final class IngressPipelineSim(val workspacePath: String) extends Simulator[Backend] {
  val backend = Backend.initializeFromProcessEnvironment()
  val tag = "verilator"
  val commonCompilationSettings = svsim.CommonCompilationSettings()
  val backendSpecificCompilationSettings = Backend.CompilationSettings.default
    // XLS codegen / xls_fifo_wrapper 的参数位宽写法触发 WIDTHEXPAND；
    // svsim 默认 warning=fatal，这里按 p4flow sim 的口径放宽常见告警。
    .withDisabledWarnings(Seq(
      "WIDTHEXPAND", "WIDTHTRUNC", "UNUSEDSIGNAL",
      "UNUSEDPARAM", "UNDRIVEN", "DECLFILENAME", "VARHIDDEN"))
    .withTraceStyle(Some(Backend.CompilationSettings.TraceStyle(
      kind = Backend.CompilationSettings.TraceKind.Fst())))

  def tracePath: String = s"$workspacePath/workdir-$tag/trace.fst"

  /** 跑一轮仿真；randomization 固定 uninitialized（chisel7 默认上电随机，
    * XLS proc 依赖复位清零，沿用 chisel5 语义）。 */
  def run[U](cycles: Int)(body: SimulatedModule[IngressPipelineSimDut] => U): U =
    simulate(new IngressPipelineSimDut,
      settings = Settings.defaultRaw[IngressPipelineSimDut].copy(
        randomization = Randomization.uninitialized))(body).result
}

object IngressPipelineSim {
  def main(args: Array[String]): Unit = {
    val cycles = if (args.nonEmpty) args(0).toInt else 100
    val ws = sys.props.getOrElse("p4xls.rtl.workspace", "out/rtl/demo12-l2l3-switch")
    val sim = new IngressPipelineSim(ws)
    sim.run(cycles) { m =>
      m.controller.setTraceEnabled(true)
      val dut = m.wrapped
      dut.reset.poke(true.B)
      dut.clock.step(5)
      dut.reset.poke(false.B)
      // TODO 功能激励：dut.io.<port>.poke(...) / peek(...)（端口见上方 Bundle）
      dut.clock.step(cycles)
      println(s"[sim] 复位 5 拍 + 空转 $cycles 拍完成")
      println(s"[sim] FST 波形：${sim.tracePath}")
    }
  }
}

